import java.util.ArrayDeque;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;

public class BoundedBlockingQueue<T> {
    private final ArrayDeque<T> queue;
    private final int capacity;
    private final ReentrantLock lock = new ReentrantLock();
    private final Condition notFull  = lock.newCondition();
    private final Condition notEmpty = lock.newCondition();
    private boolean closed = false;

    public BoundedBlockingQueue(int capacity) {
        if (capacity <= 0)
            throw new IllegalArgumentException("Capacity must be positive");
        this.capacity = capacity;
        this.queue = new ArrayDeque<>(capacity);
    }

    // ── put ─────────────────────────────────
    // Blocks until space is available or interrupted
    public void put(T item) throws InterruptedException {
        if (item == null)
            throw new NullPointerException("null items not allowed");

        lock.lockInterruptibly();
        try {
            // WHILE not IF — guards against spurious wakeups
            while (queue.size() == capacity) {
                if (closed) throw new QueueClosedException();
                notFull.await();  // releases lock, waits, re-acquires
            }
            if (closed) throw new QueueClosedException();

            queue.addLast(item);
            notEmpty.signal();  // wake ONE consumer
        } finally {
            lock.unlock();
        }
    }

    // ── take ────────────────────────────────
    // Blocks until an item is available or interrupted
    public T take() throws InterruptedException {
        lock.lockInterruptibly();
        try {
            while (queue.isEmpty()) {
                if (closed) throw new QueueClosedException();
                notEmpty.await();
            }
            T item = queue.pollFirst();
            notFull.signal();   // wake ONE producer
            return item;
        } finally {
            lock.unlock();
        }
    }

    public int size() {
        lock.lock();
        try {
            return queue.size();
        } finally {
            lock.unlock();
        }
    }
}

// ── offer with timeout ──────────────────
public boolean offer(T item, long timeout, TimeUnit unit)
        throws InterruptedException {
    if (item == null) throw new NullPointerException();

    long nanos = unit.toNanos(timeout);
    lock.lockInterruptibly();
    try {
        while (queue.size() == capacity) {
            if (closed) throw new QueueClosedException();
            if (nanos <= 0) return false;  // timeout expired
            nanos = notFull.awaitNanos(nanos);
            // awaitNanos returns remaining nanos (negative if expired)
        }
        if (closed) throw new QueueClosedException();
        queue.addLast(item);
        notEmpty.signal();
        return true;
    } finally {
        lock.unlock();
    }
}

// ── poll with timeout ───────────────────
public T poll(long timeout, TimeUnit unit) throws InterruptedException {
    long nanos = unit.toNanos(timeout);
    lock.lockInterruptibly();
    try {
        while (queue.isEmpty()) {
            if (closed) return null;  // draining closed queue
            if (nanos <= 0) return null;
            nanos = notEmpty.awaitNanos(nanos);
        }
        T item = queue.pollFirst();
        notFull.signal();
        return item;
    } finally {
        lock.unlock();
    }
}

// ── close ───────────────────────────────
public void close() {
    lock.lock();
    try {
        closed = true;
        // Wake ALL waiters so they can re-check 'closed'
        notFull.signalAll();
        notEmpty.signalAll();
    } finally {
        lock.unlock();
    }
}

class QueueClosedException extends RuntimeException {
    public QueueClosedException() {
        super("Queue is closed");
    }
}

// Demo: 2 producers, 3 consumers, capacity 5
BoundedBlockingQueue<Integer> bq = new BoundedBlockingQueue<>(5);

// Producers
for (int p = 0; p < 2; p++) {
    int id = p;
    new Thread(() -> {
        try {
            for (int i = 0; i < 100; i++) {
                bq.put(id * 1000 + i);  // blocks if full
                System.out.println("P" + id + " put " + i);
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }).start();
}

// Consumers
for (int c = 0; c < 3; c++) {
    int id = c;
    new Thread(() -> {
        try {
            while (true) {
                Integer item = bq.take();  // blocks if empty
                System.out.println("C" + id + " took " + item);
                Thread.sleep(10);  // simulate work
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }).start();
}
